solutionCode:
class Subsystem(val name: String) {
    companion object {
        var count = 0
    }

    init {
        count++
    }
}

testCode:
import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testInitialCount() {
        val startCount = Subsystem.count
        val s = Subsystem("Test")
        Assert.assertEquals(startCount + 1, Subsystem.count)
    }

    @Test
    fun testMultipleInstances() {
        val startCount = Subsystem.count
        val s1 = Subsystem("Drive")
        val s2 = Subsystem("Shooter")
        val s3 = Subsystem("Intake")
        Assert.assertEquals(startCount + 3, Subsystem.count)
    }

    @Test
    fun testNameProperty() {
        val s = Subsystem("Arm")
        Assert.assertEquals("Arm", s.name)
    }
}
